import { test, expect } from '@playwright/test';

test.describe('Task Creation Form', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks');
  });

  test('should successfully create a new task with valid form data', async ({ page }) => {
    // Verify task list is visible
    const taskList = page.getByRole('region', { name: /task list/i });
    await expect(taskList).toBeVisible();

    // Click the 'Create Task' button using getByRole
    const createButton = page.getByRole('button', { name: /create task/i });
    await createButton.click();

    // Verify task form is visible
    const taskForm = page.getByRole('form', { name: /new task/i });
    await expect(taskForm).toBeVisible();

    // Fill in task title using getByLabel
    const titleInput = page.getByLabel(/task title/i);
    await titleInput.fill('Implement user authentication');

    // Fill in description using getByLabel
    const descriptionInput = page.getByLabel(/description/i);
    await descriptionInput.fill('Set up JWT token generation and validation.');

    // Select priority using getByRole
    const prioritySelect = page.getByRole('combobox', { name: /priority/i });
    await prioritySelect.selectOption('High');

    // Select due date using getByLabel
    const dueDateInput = page.getByLabel(/due date/i);
    await dueDateInput.fill('2024-12-31');

    // Click the 'Save' button using getByRole
    const saveButton = page.getByRole('button', { name: /save task/i });
    await saveButton.click();

    // Wait for API response and form to clear
    await page.waitForResponse(response => 
      response.url().includes('/api/tasks') && response.status() === 201
    );

    // Verify success message appears
    const successMessage = page.getByText(/task created successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify task appears in the list
    const taskItem = page.getByText('Implement user authentication');
    await expect(taskItem).toBeVisible();
  });

  test('should display validation errors when submitting an empty task form', async ({ page }) => {
    // Click the 'Create Task' button using getByRole
    const createButton = page.getByRole('button', { name: /create task/i });
    await createButton.click();

    // Verify task form is visible
    const taskForm = page.getByRole('form', { name: /new task/i });
    await expect(taskForm).toBeVisible();

    // Attempt to submit the form without filling any fields
    const saveButton = page.getByRole('button', { name: /save task/i });
    await saveButton.click();

    // Wait briefly for validation to run
    await page.waitForTimeout(100);

    // Verify validation error messages appear for all required fields
    const titleError = page.getByText(/task title is required/i);
    await expect(titleError).toBeVisible();

    const descriptionError = page.getByText(/description is required/i);
    await expect(descriptionError).toBeVisible();

    const priorityError = page.getByText(/priority is required/i);
    await expect(priorityError).toBeVisible();

    // Verify task list remains unchanged
    const taskList = page.getByRole('region', { name: /task list/i });
    await expect(taskList).toBeVisible();

    // Verify no success message is displayed
    const successMessage = page.getByText(/task created successfully/i);
    await expect(successMessage).not.toBeVisible();
  });
});
